values ('event-dmuseum-taste-house-2', (select id from public.couple_venues where source_key = 'venue-d-museum'), 'event', '취향가옥 2: Art in Life, Life in Art 2', '집이라는 익숙한 공간 안에서 미술·디자인·가구와 수집 취향을 함께 발견하는 디뮤지엄 기획 전시입니다.', 'exhibition', array['exhibition_popup', 'walk_culture']::text[], 'exhibition_popup', array['walk_culture']::text[], 'low', 'new', 'temporary', '디뮤지엄 공식 페이지에 2026년 9월 20일까지의 전시 기간과 현재 예매가 확인됩니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-09-15T12:00:00+09:00'::timestamptz, '2026-09-21T00:00:00+09:00'::timestamptz, 'under_20000', 12000, 12000, 'admission', '성인 일반 관람료 12,000원, 공식 예매 페이지 기준', 150, 'indoor', 'low', 'medium', false, 4, 'active', '2025-06-28T00:00:00+09:00'::timestamptz, '2026-09-21T00:00:00+09:00'::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://daelimmuseum.org/exhibition/current/PRG202506050001","checked_at":"2026-09-01"}]'::jsonb, 5, 5, 4, 5, 5, 2, 91, 'hero', '생활 공간과 예술을 결합한 현재 전시로 성수 데이트의 목적성과 함께 볼 대화거리가 모두 분명합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-09-15T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://daelimmuseum.org/exhibition/current/PRG202506050001","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', false, null, null::timestamptz, null::timestamptz, 'available', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-09-15T12:00:00+09:00'::timestamptz, 'production', 'couple-production-phase1b2a-v1', now())
