values ('item-dotnote-seongsu', (select id from public.couple_venues where source_key = 'venue-dotnote-seongsu'), 'permanent', '성수향수공방 닷노트', '각자 향을 고르고 조합해 서로 다른 결과물을 가져가는 1~2시간 조향 체험 공간입니다.', 'experience', array['experience']::text[], 'experience', array[]::text[], 'medium', 'proven', 'evergreen', '공식 홈페이지와 2026년 운영 후기에서 성수점 조향 체험과 영업시간을 확인했습니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-11-30T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_40000', 35000, 35000, 'program_fee', '대표 조향 체험 예상가, 용량·프로그램별 변동', 120, 'indoor', 'low', 'low', false, 4, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://dotnote.co.kr/","checked_at":"2026-09-01"}]'::jsonb, 5, 4, 4, 4, 5, 3, 79, 'standard', '각자의 취향을 향으로 만들고 결과물을 가져가는 공동 제작형 체험이라 커플 데이트 목적성이 높습니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-12-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://dotnote.co.kr/","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', true, 'https://dotnote.co.kr/', null::timestamptz, null::timestamptz, 'available', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'production', 'couple-production-phase1b2a-v1', now())
