values ('item-dialogue-in-dark', (select id from public.couple_venues where source_key = 'venue-dialogue-in-dark'), 'permanent', '어둠속의대화', '완전한 어둠 속에서 소리·촉감·대화에 의지해 함께 이동하는 독특한 감각 체험입니다.', 'experience', array['experience']::text[], 'experience', array[]::text[], 'medium', 'balanced', 'evergreen', '공식 사이트와 Kakao 장소에서 북촌 체험 운영을 확인했고 예약 가능 상태를 월별 검수합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-31T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_40000', 30000, 30000, 'program_fee', '성인 체험 1인 예상가, 공식 예매에서 최종 확인', 150, 'indoor', 'medium', 'low', false, 3, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://www.dialogueinthedark.co.kr/","checked_at":"2026-09-01"}]'::jsonb, 5, 5, 5, 5, 5, 2, 95, 'hero', '어둠 속에서 서로 의지하는 독특한 체험으로 공동 경험과 대화 가치가 매우 높은 목적형 데이트입니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-12-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://www.dialogueinthedark.co.kr/","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', true, 'https://www.dialogueinthedark.co.kr/', null::timestamptz, null::timestamptz, 'available', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'production', 'couple-production-phase1b2a-v1', now())
