values ('item-peakers-jongno', (select id from public.couple_venues where source_key = 'venue-peakers-jongno'), 'permanent', '피커스 종로점', '종로 한복판에서 장비를 빌려 함께 볼더링에 도전하고 성취를 공유하는 실내 활동 공간입니다.', 'experience', array['experience']::text[], 'experience', array[]::text[], 'high', 'balanced', 'evergreen', '피커스 공식 채널과 Kakao 장소에서 종로점 운영을 확인했고 이용료를 분기별 검수합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-31T12:00:00+09:00'::timestamptz, null::timestamptz, 'under_40000', 25000, 22000, 'admission', '일일권과 장비 대여를 포함한 1인 예상 지출', 180, 'indoor', 'high', 'low', false, 5, 'active', null::timestamptz, null::timestamptz, '2026-09-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://peakers.co.kr/","checked_at":"2026-09-01"}]'::jsonb, 5, 5, 4, 5, 5, 2, 91, 'hero', '도심에서 함께 도전하고 응원하는 클라이밍 경험으로 종로의 부족한 high energy 선택지를 강하게 보완합니다.', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-11-01T12:00:00+09:00'::timestamptz, '[{"kind":"official","url":"https://peakers.co.kr/","checked_at":"2026-09-01"}]'::jsonb, 'couple-editorial-v1', 'independent_couple_research', false, null, null::timestamptz, null::timestamptz, 'walk_in_only', '2026-09-01T12:00:00+09:00'::timestamptz, '2026-10-01T12:00:00+09:00'::timestamptz, 'production', 'couple-production-phase1b2a-v1', now())
